package com.veltrix.study;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
public final class StudyDatabase extends SQLiteOpenHelper{
 public StudyDatabase(Context c){super(c,"veltrix_study.db",null,1);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE topics(id TEXT PRIMARY KEY,week INTEGER,day INTEGER,subject TEXT,title TEXT,done INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,body TEXT,created_at INTEGER)");d.execSQL("CREATE TABLE scores(id INTEGER PRIMARY KEY AUTOINCREMENT,subject TEXT,score INTEGER,total INTEGER,created_at INTEGER)");d.execSQL("CREATE TABLE questions(id TEXT PRIMARY KEY,subject TEXT,year INTEGER,prompt TEXT,a TEXT,b TEXT,c TEXT,d TEXT,answer TEXT,explanation TEXT,source_url TEXT,verified INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,started_at INTEGER,submitted_at INTEGER,duration_seconds INTEGER DEFAULT 7200,total INTEGER DEFAULT 180,score INTEGER)");d.execSQL("CREATE TABLE attempt_answers(attempt_id INTEGER,question_id TEXT,selected TEXT,PRIMARY KEY(attempt_id,question_id))");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){}
 public void seed(String[][] p){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{for(int w=0;w<p.length;w++)for(int i=0;i<p[w].length;i++){String[] a=p[w][i].split("\\|",2);ContentValues v=new ContentValues();v.put("id","w"+(w+1)+"t"+i);v.put("week",w+1);v.put("day",i/2);v.put("subject",a[0]);v.put("title",a[1]);d.insertWithOnConflict("topics",null,v,SQLiteDatabase.CONFLICT_IGNORE);}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 public int count(String sql){try(Cursor c=getReadableDatabase().rawQuery(sql,null)){return c.moveToFirst()?c.getInt(0):0;}}
 public int done(){return count("SELECT COUNT(*) FROM topics WHERE done=1");}public int total(){return count("SELECT COUNT(*) FROM topics");}public int verifiedQuestions(){return count("SELECT COUNT(*) FROM questions WHERE verified=1");}
 public void tick(String id,boolean b){ContentValues v=new ContentValues();v.put("done",b?1:0);getWritableDatabase().update("topics",v,"id=?",new String[]{id});}
 public List<Topic> topics(int w){List<Topic> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,day,subject,title,done FROM topics WHERE week=? ORDER BY day,id",new String[]{""+w})){while(c.moveToNext())a.add(new Topic(c.getString(0),c.getInt(1),c.getString(2),c.getString(3),c.getInt(4)==1));}return a;}
 public void note(String t,String b){ContentValues v=new ContentValues();v.put("title",t);v.put("body",b);v.put("created_at",System.currentTimeMillis());getWritableDatabase().insert("notes",null,v);}
 public List<Note> notes(){List<Note>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT title,body,created_at FROM notes ORDER BY id DESC",null)){while(c.moveToNext())a.add(new Note(c.getString(0),c.getString(1),c.getLong(2)));}return a;}
 public void score(String s,int x,int t){ContentValues v=new ContentValues();v.put("subject",s);v.put("score",x);v.put("total",t);v.put("created_at",System.currentTimeMillis());getWritableDatabase().insert("scores",null,v);}
 public List<Score> scores(){List<Score>a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT subject,score,total,created_at FROM scores ORDER BY id DESC",null)){while(c.moveToNext())a.add(new Score(c.getString(0),c.getInt(1),c.getInt(2),c.getLong(3)));}return a;}
 public static class Topic{public String id,subject,title;public int day;public boolean done;Topic(String i,int d,String s,String t,boolean b){id=i;day=d;subject=s;title=t;done=b;}}
 public static class Note{public String title,body;public long date;Note(String t,String b,long d){title=t;body=b;date=d;}}
 public static class Score{public String subject;public int score,total;public long date;Score(String s,int x,int t,long d){subject=s;score=x;total=t;date=d;}}
}